<template><div class="table-page receptors-page"><div class="page-toolbar"><el-tag type="primary">{{ regionName }}</el-tag><el-button type="primary" icon="el-icon-plus" @click="openCreate">新增受体点</el-button><el-button type="success" icon="el-icon-check" @click="enableAll">全部启用</el-button><el-button type="warning" icon="el-icon-close" @click="disableAll">全部停用</el-button><el-button type="danger" icon="el-icon-delete" :disabled="selected.length===0" @click="removeSelected">批量删除 ({{ selected.length }})</el-button><span class="spacer"/><el-button type="text" icon="el-icon-refresh" @click="refresh">刷新</el-button></div><div class="table-shell"><el-table v-loading="loading" :data="items" border stripe row-key="id" @selection-change="selected=$event"><el-table-column type="selection" width="46"/><el-table-column prop="id" label="ID" width="60"/><el-table-column prop="name" label="名称"/><el-table-column prop="latitude" label="纬度"/><el-table-column prop="longitude" label="经度"/><el-table-column prop="height" label="高度"/><el-table-column label="启用"><template slot-scope="s"><el-switch v-model="s.row.isActive" @change="setActive(s.row,$event)"/></template></el-table-column><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="openEdit(s.row)">编辑</el-button><el-button type="text" style="color:#f56c6c" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div><el-dialog :visible.sync="dialogVisible" :title="dialogMode==='create'?'新增受体点':'编辑受体点'" width="480px"><el-form label-width="100px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="纬度"><el-input-number v-model="form.latitude" :precision="6"/></el-form-item><el-form-item label="经度"><el-input-number v-model="form.longitude" :precision="6"/></el-form-item><el-form-item label="高度"><el-input-number v-model="form.height"/></el-form-item><el-form-item label="是否启用"><el-switch v-model="form.isActive"/></el-form-item></el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></span></el-dialog></div></template>
<script lang="ts">import Vue from 'vue'; import { receptorsApi } from '@/api'; import type { Receptor } from '@/types'; export default Vue.extend({name:'ReceptorsView',data:()=>({items:[] as Receptor[],loading:false,selected:[] as Receptor[],dialogVisible:false,dialogMode:'create',editId:null as number|null,form:{name:'',latitude:39.9,longitude:116.4,height:1.5,markerSymbol:'monitor',markerColor:'#2196F3',isActive:true} as any}),computed:{regionName():string{return this.$store.state.regions.find((r:any)=>r.key===this.$store.state.currentRegionKey)?.name||''}},mounted(){this.refresh()},methods:{async refresh(){this.loading=true;try{this.items=await receptorsApi.list(0,1000,this.$store.state.currentRegionKey);this.selected=[]}finally{this.loading=false}},openCreate(){this.dialogMode='create';this.editId=null;Object.assign(this.form,{name:'',latitude:39.9,longitude:116.4,height:1.5,isActive:true});this.dialogVisible=true},openEdit(r:Receptor){this.dialogMode='edit';this.editId=r.id;Object.assign(this.form,r);this.dialogVisible=true},async submit(){if(this.dialogMode==='create')await receptorsApi.create(this.form,this.$store.state.currentRegionKey);else if(this.editId)await receptorsApi.update(this.editId,this.form);this.dialogVisible=false;this.refresh()},async setActive(r:Receptor,isActive:boolean){await receptorsApi.update(r.id,{isActive});this.refresh()},async enableAll(){await Promise.all(this.items.filter(i=>!i.isActive).map(i=>receptorsApi.update(i.id,{isActive:true})));this.refresh()},async disableAll(){await Promise.all(this.items.filter(i=>i.isActive).map(i=>receptorsApi.update(i.id,{isActive:false})));this.refresh()},async remove(r:Receptor){await receptorsApi.delete(r.id);this.refresh()},async removeSelected(){await Promise.all(this.selected.map(r=>receptorsApi.delete(r.id)));this.refresh()}}})</script>
